package com.example.cardservice.service;
import com.example.cardservice.config.CardProperties;import com.example.cardservice.dto.AuthorizationRequest;import com.example.cardservice.entity.*;import com.example.cardservice.repository.*;import org.junit.jupiter.api.*;import java.math.BigDecimal;import java.time.*;import java.util.Optional;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class CardServiceTest{@Test void rejectsInsufficientFunds(){var cr=mock(DebitCardRepository.class);var tr=mock(CardTransactionRepository.class);var customer=new Customer("C1","Test");var card=new DebitCard("t","**** 1",new BigDecimal("10"),LocalDate.of(2030,1,1),customer);when(cr.findByCardToken("t")).thenReturn(Optional.of(card));when(tr.findByIdempotencyKey("k")).thenReturn(Optional.empty());var s=new CardService(cr,tr,new CardProperties(new BigDecimal("100"),new BigDecimal("50")),Clock.fixed(Instant.parse("2026-01-01T00:00:00Z"),ZoneOffset.UTC));assertThrows(RuntimeException.class,()->s.authorize("t",new AuthorizationRequest("k",new BigDecimal("20"),"INR","Store")));}}
